// Учебный обмен с ОДНИМ датчиком, не готовый режим R1.
transfer16(0xFFFF);          // запрос Angle, CSn = 0 на 16 тактов
raw = transfer16(0x0000);    // следующий обмен, отдельный CSn
if (!evenParity(raw) || (raw & 0x4000)) reject();
N = raw & 0x3FFF;            // диапазон 0..16383
// Между обменами CSn возвращается в 1.
